// travel forecast display (domestic + international variants)
import STATUS from './status.mjs';
import { safeJson, safePromiseAll } from './utils/fetch.mjs';
import { getSmallIcon } from './icons.mjs';
import { distance as calcDistance } from './utils/calc.mjs';
import { DateTime } from '../vendor/auto/luxon.mjs';
import WeatherDisplay from './weatherdisplay.mjs';
import { registerDisplay } from './navigation.mjs';
import settings from './settings.mjs';
import calculateScrollTiming from './utils/scroll-timing.mjs';
import { debugFlag } from './utils/debug.mjs';

// Cities within this many degrees of the user's location are treated as
// "home" and excluded from the travel list. ~0.35 degrees is roughly a
// 25-mile radius at US latitudes, which comfortably covers a metro area
// without accidentally excluding a genuinely different nearby city.
const HOME_CITY_RADIUS_DEGREES = 0.35;

// Open-Meteo WMO weather code -> WeatherStar icon, used for any city that
// doesn't have a pre-computed NWS gridpoint (i.e. international cities, and
// any domestic city added without running the travelcities data generator).
const getOpenMeteoIcon = (code, isNight = false) => {
	const path = (icon) => `images/icons/regional-maps/${icon}`;
	switch (true) {
		case code === 0: return path(isNight ? 'Clear-1992.gif' : 'Sunny.gif');
		case code === 1: return path(isNight ? 'Partly-Clear-1994.gif' : 'Partly-Cloudy.gif');
		case code === 2: return path('Partly-Cloudy.gif');
		case code === 3: return path('Cloudy.gif');
		case code >= 45 && code <= 48: return path('Fog.gif');
		case code >= 51 && code <= 57:
		case code >= 61 && code <= 65: return path('Rain-1992.gif');
		case code === 66 || code === 67: return path('Freezing-Rain-1992.gif');
		case code >= 71 && code <= 75:
		case code === 77: return path('Light-Snow.gif');
		case code >= 80 && code <= 82: return path('Scattered-Showers-1994.gif');
		case code >= 85 && code <= 86: return path('Heavy-Snow-1994.gif');
		case code === 95: return path(isNight ? 'Scattered-Tstorms-Night-1994.gif' : 'Scattered-Tstorms-1994.gif');
		case code >= 96: return path('Thunderstorm.gif');
		default: return path(isNight ? 'Clear-1992.gif' : 'Sunny.gif');
	}
};

// Fetch a 2-day forecast from Open-Meteo for a city that has no NWS gridpoint.
const getOpenMeteoForecast = async (city) => {
	const url = `https://api.open-meteo.com/v1/forecast?latitude=${city.Latitude}&longitude=${city.Longitude}&daily=temperature_2m_max,temperature_2m_min,weather_code&temperature_unit=fahrenheit&timezone=auto&forecast_days=2`;
	const controller = new AbortController();
	const timeoutHandle = setTimeout(() => controller.abort(), 8000);
	try {
		const response = await fetch(url, { signal: controller.signal });
		clearTimeout(timeoutHandle);
		if (!response.ok) return { name: city.Name, error: true };
		const data = await response.json();
		const high = data?.daily?.temperature_2m_max?.[0];
		if (high === undefined) return { name: city.Name, error: true };
		const low = data.daily.temperature_2m_min[0];
		const code = data.daily.weather_code?.[0] ?? data.daily.weathercode?.[0] ?? 0;
		// Open-Meteo doesn't return a day/night flag for the daily summary,
		// so approximate using local wall-clock time (the API was asked for
		// timezone=auto, which localizes the returned daily values).
		const hourNow = (new Date()).getHours();
		const isNight = hourNow < 6 || hourNow >= 20;
		return {
			today: true,
			high: Math.round(high),
			low: Math.round(low),
			name: city.Name,
			icon: getOpenMeteoIcon(code, isNight),
		};
	} catch (_error) {
		clearTimeout(timeoutHandle);
		return { name: city.Name, error: true };
	}
};

class TravelForecast extends WeatherDisplay {
	constructor(navId, elemId, displayName, defaultActive, getCities) {
		super(navId, elemId, displayName, defaultActive);

		// function that returns the current city list (e.g. window.TravelCitiesDomestic)
		this.getCities = getCities;

		// add previous data cache
		this.previousData = [];

		// cache for scroll calculations
		// This cache is essential because baseCountChange() is called 25 times per second (every 40ms)
		// during scrolling. Travel forecast scroll duration varies based on the number of cities configured.
		// Without caching, we'd perform hundreds of expensive DOM layout queries during each scroll cycle.
		// The cache reduces this to one calculation when content changes, then reuses cached values to try
		// and get smoother scrolling.
		this.scrollCache = {
			displayHeight: 0,
			contentHeight: 0,
			maxOffset: 0,
			travelLines: null,
		};
	}

	// Filter out any city that's effectively the user's own location, so the
	// travel list doesn't redundantly include the forecast they already see
	// on Local Forecast / Current Conditions.
	getFilteredCities() {
		const allCities = this.getCities() ?? [];
		const { latitude, longitude } = this.weatherParameters ?? {};
		if (latitude === undefined || longitude === undefined) return allCities;

		return allCities.filter((city) => {
			if (city.Latitude === undefined || city.Longitude === undefined) return true;
			const dist = calcDistance(city.Longitude, city.Latitude, longitude, latitude);
			return dist > HOME_CITY_RADIUS_DEGREES;
		});
	}

	async getData(weatherParameters, refresh) {
		// super checks for enabled
		if (!super.getData(weatherParameters, refresh)) return;

		// clear stored data if not refresh
		if (!refresh) {
			this.previousData = [];
		}

		const cities = this.getFilteredCities();

		const forecastPromises = cities.map(async (city, index) => {
			try {
				// US cities with a pre-computed NWS gridpoint use the NWS API;
				// everything else (international, or any domestic city added
				// without running the data generator) falls back to Open-Meteo.
				if (!city.point) return getOpenMeteoForecast(city);

				let forecast;
				forecast = await safeJson(`https://api.weather.gov/gridpoints/${city.point.wfo}/${city.point.x},${city.point.y}/forecast`, {
					data: {
						units: settings.units.value,
					},
				});

				if (forecast) {
					// store for the next run
					this.previousData[index] = forecast;
				} else if (this.previousData?.[index]) {
					// if there's previous data use it
					if (debugFlag('travelforecast')) {
						console.warn(`Using previous forecast data for ${city.Name} travel forecast`);
					}
					forecast = this.previousData?.[index];
				} else {
					// no current data and no previous data available
					if (debugFlag('verbose-failures')) {
						console.warn(`No travel forecast for ${city.Name} available`);
					}
					return { name: city.Name, error: true };
				}
				// determine today or tomorrow (shift periods by 1 if tomorrow)
				const todayShift = forecast.properties.periods[0].isDaytime ? 0 : 1;
				// return a pared-down forecast
				return {
					today: todayShift === 0,
					high: forecast.properties.periods[todayShift].temperature,
					low: forecast.properties.periods[todayShift + 1].temperature,
					name: city.Name,
					icon: getSmallIcon(forecast.properties.periods[todayShift].icon),
				};
			} catch (error) {
				console.error(`Unexpected error getting Travel Forecast for ${city.Name}: ${error.message}`);
				return { name: city.Name, error: true };
			}
		});

		// wait for all forecasts using centralized safe Promise handling
		const forecasts = await safePromiseAll(forecastPromises);
		this.data = forecasts;

		// test for some data available in at least one forecast
		const hasData = this.data.some((forecast) => forecast.high);
		if (!hasData) {
			this.setStatus(STATUS.noData);
			return;
		}

		this.setStatus(STATUS.loaded);
		this.drawLongCanvas();
	}

	async drawLongCanvas() {
		// get the element and populate
		const list = this.elem.querySelector('.travel-lines');
		list.innerHTML = '';

		// set up variables
		const cities = this.data;

		const lines = cities.map((city) => {
			if (city.error) return false;
			const fillValues = {
				city,
			};

			// check for forecast data
			if (city.icon) {
				fillValues.city = city.name;
				// get temperatures and convert if necessary
				const { low, high } = city;

				// convert to strings with no decimal
				const lowString = Math.round(low).toString();
				const highString = Math.round(high).toString();

				fillValues.low = lowString;
				fillValues.high = highString;
				const { icon } = city;

				fillValues.icon = { type: 'img', src: icon };
			} else {
				fillValues.error = 'NO TRAVEL DATA AVAILABLE';
			}
			return this.fillTemplate('travel-row', fillValues);
		}).filter((d) => d);
		list.append(...lines);

		// reset the scroll cache so the next baseCountChange recalculates
		// against the freshly-populated list (handles both initial load and
		// data refreshes where the city count may have changed)
		this.scrollCache.travelLines = null;
		this.scrollCache.displayHeight = 0;

		// update timing based on actual content
		this.setTiming(list);
	}

	async drawCanvas() {
		// there are technically 2 canvases: the standard canvas and the extra-long canvas that contains the complete
		// list of cities. The second canvas is copied into the standard canvas to create the scroll
		super.drawCanvas();

		// set up variables
		const cities = this.data;

		this.elem.querySelector('.header .title.dual .bottom').innerHTML = `For ${getTravelCitiesDayName(cities)}`;

		this.finishDraw();
	}

	async showCanvas() {
		// special to travel forecast to draw the remainder of the canvas
		await this.drawCanvas();
		super.showCanvas();

		// If this display loaded its data while off-screen (height: 0), the
		// initial setTiming() call in drawLongCanvas() would have measured a
		// zero-height container and produced pixelsPerCount = 0, leaving the
		// scroll permanently "stuck" at the top. This happens specifically
		// when this display is the ONLY one enabled, since in that case it's
		// never preceded by another display's showCanvas() (which is what
		// incidentally fixes the layout in multi-display configurations).
		// Now that we're definitely visible (showCanvas just ran), recompute
		// the timing against real, on-screen measurements and self-heal.
		const travelLines = this.elem.querySelector('.travel-lines');
		if (travelLines && this.scrollTiming?.pixelsPerCount === 0) {
			const container = this.elem.querySelector('.main');
			const scrollableHeight = Math.max(0, travelLines.offsetHeight - container.offsetHeight);
			if (scrollableHeight > 0) {
				// force a fresh measurement on the next baseCountChange
				this.scrollCache.travelLines = null;
				this.scrollCache.displayHeight = 0;
				this.setTiming(travelLines);
			}
		}
	}

	// screen index change callback just runs the base count callback
	screenIndexChange() {
		this.baseCountChange(this.navBaseCount);
	}

	// base count change callback
	baseCountChange(count) {
		// get the travel lines element and cache measurements if needed
		const travelLines = this.elem.querySelector('.travel-lines');
		if (!travelLines) return;

		// update cache if needed (when content changes or first run)
		if (this.scrollCache.travelLines !== travelLines || this.scrollCache.displayHeight === 0) {
			this.scrollCache.displayHeight = this.elem.querySelector('.main').offsetHeight;
			this.scrollCache.contentHeight = travelLines.offsetHeight;
			this.scrollCache.maxOffset = Math.max(0, this.scrollCache.contentHeight - this.scrollCache.displayHeight);
			this.scrollCache.travelLines = travelLines;

			// Set up hardware acceleration on the travel lines element
			travelLines.style.willChange = 'transform';
			travelLines.style.backfaceVisibility = 'hidden';

			// Self-heal: if our cached scroll timing says there's nothing to
			// scroll (pixelsPerCount === 0) but a fresh, on-screen
			// measurement says there IS scrollable content, the original
			// setTiming() call ran against a zero-height (off-screen)
			// container. Recalculate now that real dimensions are available.
			if (this.scrollCache.maxOffset > 0 && this.scrollTiming?.pixelsPerCount === 0) {
				this.setTiming(travelLines);
			}
		}

		// calculate scroll offset and don't go past end
		let offsetY = Math.min(this.scrollCache.maxOffset, (count - this.scrollTiming.initialCounts) * this.scrollTiming.pixelsPerCount);

		// don't let offset go negative
		if (offsetY < 0) offsetY = 0;

		// use transform instead of scrollTo for hardware acceleration
		travelLines.style.transform = `translateY(-${Math.round(offsetY)}px)`;
	}

	// necessary to get the lastest long canvas when scrolling
	getLongCanvas() {
		return this.longCanvas;
	}

	setTiming(list) {
		const container = this.elem.querySelector('.main');
		const timingConfig = calculateScrollTiming(list, container, {
			staticDisplay: 5.0, // special static display time for travel forecast
		});

		// Apply the calculated timing
		this.timing.baseDelay = timingConfig.baseDelay;
		this.timing.delay = timingConfig.delay;
		this.scrollTiming = timingConfig.scrollTiming;

		this.calcNavTiming();
	}
}

// effectively returns early on the first found date
const getTravelCitiesDayName = (cities) => cities.reduce((dayName, city) => {
	if (city && dayName === '') {
		// today or tomorrow
		const day = DateTime.local().plus({ days: (city.today) ? 0 : 1 });
		// return the day
		return day.toLocaleString({ weekday: 'long' });
	}
	return dayName;
}, '');

// register both displays, not active by default.
// navId 5 keeps the position previously used by the single combined
// Travel Forecast display; navId 12 is appended after Radar (11).
registerDisplay(new TravelForecast(5, 'travel-domestic', 'Domestic Travel', false, () => window.TravelCitiesDomestic));
registerDisplay(new TravelForecast(12, 'travel-international', 'International Travel', false, () => window.TravelCitiesInternational));
